package com.fandazi.feature.order;
import com.fandazi.feature.delivery.DeliveryService; import com.fandazi.feature.payment.PaymentService; import org.springframework.http.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/orders") public class OrderController { private final OrderService orders; private final PaymentService payments; private final DeliveryService delivery; public OrderController(OrderService orders,PaymentService payments,DeliveryService delivery){this.orders=orders;this.payments=payments;this.delivery=delivery;} public record CreateRequest(Long cartDraftId,Long addressId){} public record AdvanceRequest(OrderStatus status){} @PostMapping public ResponseEntity<OrderEntity> create(@AuthenticationPrincipal Long userId,@RequestHeader("Idempotency-Key") String key,@RequestBody CreateRequest request){return ResponseEntity.status(HttpStatus.CREATED).body(orders.create(userId,new CreateOrderCommand(request.cartDraftId(),request.addressId(),key)));}@PostMapping("/{id}/pay") public OrderEntity pay(@AuthenticationPrincipal Long userId,@PathVariable Long id){return payments.pay(userId,id);}@GetMapping("/{id}") public OrderEntity get(@AuthenticationPrincipal Long userId,@PathVariable Long id){return orders.get(userId,id);}@PostMapping("/{id}/delivery") public OrderEntity advance(@AuthenticationPrincipal Long userId,@PathVariable Long id,@RequestBody AdvanceRequest request){return delivery.advance(userId,id,request.status());} }
